import Foundation

/// A simple, explicitly declared mass model for the Milky Way.
///
/// The rotation curve is not an arbitrary tanh fit: it is the circular speed
/// generated by a Hernquist bulge + Miyamoto-Nagai disk + NFW halo. The same
/// model is used by the volume shader, the star-particle initial conditions and
/// the restricted N-body integrator, so all layers share one potential.
enum AstroModel {
    // Units: kpc, km/s, Msun. G in kpc (km/s)^2 / Msun.
    static let G = 4.30091e-6

    // Hernquist bulge
    static let bulgeMass = 1.0e10
    static let bulgeScale = 0.8

    // Miyamoto-Nagai disk (stars + gas)
    static let diskMass = 7.0e10
    static let diskScaleLength = 4.0
    static let diskScaleHeight = 0.30

    // NFW halo
    static let haloMass200 = 1.2e12
    static let haloScaleRadius = 25.0
    static let haloConcentration = 8.0

    static let kmPerSecToKpcPerMyr = 0.0010227
    static let patternSpeed = 0.024 // rad / Myr, ~23.5 km/s/kpc

    static func bulgeV2(_ r: Double) -> Double {
        G * bulgeMass * r / pow(r + bulgeScale, 2.0)
    }

    static func diskV2(_ r: Double) -> Double {
        G * diskMass * r * r / pow(r * r + diskScaleLength * diskScaleLength, 1.5)
    }

    static func haloV2(_ r: Double) -> Double {
        let c = haloConcentration
        let x = r / haloScaleRadius
        let f = log(1.0 + x) - x / (1.0 + x)
        let fc = log(1.0 + c) - c / (1.0 + c)
        return G * haloMass200 * (f / fc) / max(r, 0.05)
    }

    static func circularSpeed(_ r: Double) -> Double {
        let radius = max(r, 0.02)
        return sqrt(max(0.0, bulgeV2(radius) + diskV2(radius) + haloV2(radius)))
    }

    /// Angular speed in rad/Myr.
    static func angularSpeed(_ r: Double) -> Double {
        let radius = max(r, 0.18)
        return circularSpeed(radius) / radius * kmPerSecToKpcPerMyr
    }

    /// Radius where the material angular speed matches the spiral pattern speed.
    static func corotationRadius() -> Double {
        var lo = 0.2
        var hi = 30.0
        for _ in 0..<60 {
            let mid = 0.5 * (lo + hi)
            if angularSpeed(mid) > patternSpeed { lo = mid } else { hi = mid }
        }
        return 0.5 * (lo + hi)
    }
}
